// Build inclusive card pools by group so all 363 playable/blueprint/rumor cards are obtainable via packs or gameplay
const mainlandResources = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'mainland' && ['resource', 'harvestable', 'food', 'animal', 'villager'].includes(c.category) && c.id !== 'kid',
).map((c) => ({ cardId: c.id, weight: c.id === 'villager' ? 1 : 5 }));

const mainlandIdeas = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'mainland' && (c.category === 'blueprint' || c.category === 'rumor'),
).map((c) => ({ cardId: c.id, weight: 4 }));

const mainlandBuildingsAndEquip = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'mainland' && ['building', 'equipable', 'container', 'boat', 'portal', 'enemy', 'corpse', 'currency'].includes(c.category),
).map((c) => ({ cardId: c.id, weight: 3 }));

const islandPool = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'island' && c.category !== 'system' && c.category !== 'blueprint',
).map((c) => ({ cardId: c.id, weight: 4 }));

const islandIdeas = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'island' && (c.category === 'blueprint' || c.category === 'rumor'),
).map((c) => ({ cardId: c.id, weight: 4 }));

const forestPool = RAW_LEDGER_CARDS.filter(
  (c) => c.region === 'forest' && c.category !== 'system',
).map((c) => ({ cardId: c.id, weight: 4 }));

