export type LedgerIntegrityReport = {
  valid: boolean;
  totalLedgerEntries: number;
  inScopeEntries: number;
  excludedEntries: number;
  implementedEntries: number;
  recipeCount: number;
  packCount: number;
  questCount: number;
  errors: string[];
};

export function validateContentIntegrity(): LedgerIntegrityReport {
  const errors: string[] = [];
  const seenCardIds = new Set<string>();

  for (const card of RAW_LEDGER_CARDS) {
    if (seenCardIds.has(card.id)) {
      errors.push(`Duplicate card ID: ${card.id}`);
    }
    seenCardIds.add(card.id);
    if (card.category === 'system' && !card.excludedReason) {
      errors.push(`System card missing excludedReason: ${card.id}`);
    }
    if (card.harvestDrops) {
      for (const drop of card.harvestDrops) {
        if (!CARD_MAP[drop.cardId]) {
          errors.push(`Card ${card.id} harvestDrop references unknown card ${drop.cardId}`);
        }
        if (drop.weight <= 0) {
          errors.push(`Card ${card.id} harvestDrop has non-positive weight for ${drop.cardId}`);
        }
      }
    }
    if (card.roleOnEquip && !CARD_MAP[card.roleOnEquip]) {
      errors.push(`Card ${card.id} roleOnEquip references unknown villager card ${card.roleOnEquip}`);
    }
  }

  const reachableIds = new Set<string>(['villager', 'berrybush', 'wood', 'stone', 'gold', 'shell', 'corpse', 'poop', 'goop']);

  for (const pack of BOOSTER_PACKS) {
    if (!CARD_MAP[pack.currencyCardId]) {
      errors.push(`Pack ${pack.id} references unknown currency ${pack.currencyCardId}`);
    }
    for (const slot of pack.slots) {
      if (slot.pool.length === 0) {
        errors.push(`Pack ${pack.id} has empty slot ${slot.label}`);
      }
      for (const item of slot.pool) {
        if (!CARD_MAP[item.cardId]) {
          errors.push(`Pack ${pack.id} references unknown card ${item.cardId}`);
        } else {
          reachableIds.add(item.cardId);
        }
      }
    }
  }

  for (const recipe of RECIPES) {
    if (recipe.durationTicks <= 0) {
      errors.push(`Recipe ${recipe.id} has invalid durationTicks`);
    }
    for (const [inputId, qty] of Object.entries(recipe.inputs)) {
      if (!CARD_MAP[inputId]) {
        errors.push(`Recipe ${recipe.id} references unknown input ${inputId}`);
      }
      if (qty <= 0) {
        errors.push(`Recipe ${recipe.id} input ${inputId} has invalid quantity`);
      }
    }
    for (const catId of recipe.catalysts) {
      if (!CARD_MAP[catId]) {
        errors.push(`Recipe ${recipe.id} references unknown catalyst ${catId}`);
      }
    }
    if (recipe.ideaCardId && !CARD_MAP[recipe.ideaCardId]) {
      errors.push(`Recipe ${recipe.id} references unknown ideaCardId ${recipe.ideaCardId}`);
    }
    for (const out of recipe.outputs) {
      if (!CARD_MAP[out.cardId]) {
        errors.push(`Recipe ${recipe.id} references unknown output ${out.cardId}`);
      } else {
        reachableIds.add(out.cardId);
      }
    }
  }

  for (const card of RAW_LEDGER_CARDS) {
    if (card.harvestDrops) {
      for (const drop of card.harvestDrops) {
        reachableIds.add(drop.cardId);
      }
    }
    if (card.roleOnEquip) {
      reachableIds.add(card.roleOnEquip);
    }
  }

  for (const quest of QUESTS) {
    if (quest.condition.targetId && !['mainland', 'island', 'forest'].includes(quest.condition.targetId) && !CARD_MAP[quest.condition.targetId]) {
      errors.push(`Quest ${quest.id} references unknown targetId ${quest.condition.targetId}`);
    }
    if (quest.rewardCardId) {
      if (!CARD_MAP[quest.rewardCardId]) {
        errors.push(`Quest ${quest.id} references unknown rewardCardId ${quest.rewardCardId}`);
      } else {
        reachableIds.add(quest.rewardCardId);
      }
    }
  }

  const inScope = RAW_LEDGER_CARDS.filter((c) => c.category !== 'system');
  const excluded = RAW_LEDGER_CARDS.filter((c) => c.category === 'system');
  for (const card of inScope) {
    if (!reachableIds.has(card.id)) {
      errors.push(`In-scope card has no acquisition path: ${card.id}`);
    }
  }

  return {
    valid: errors.length === 0,
    totalLedgerEntries: RAW_LEDGER_CARDS.length,
    inScopeEntries: inScope.length,
    excludedEntries: excluded.length,
    implementedEntries: inScope.filter((c) => c.verification === 'implemented' || c.verification === 'verified').length,
    recipeCount: RECIPES.length,
    packCount: BOOSTER_PACKS.length,
    questCount: QUESTS.length,
    errors,
  };
}
